using System;using System.Reflection;using Microsoft.VisualStudio.TestTools.UnitTesting;using SAEA.Common.Caching;using SAEA.Sockets.Pipeline;namespace SAEA.Sockets.Pipeline.Tests.Tests.Runtime{    [TestClass]    public class PooledMessageTests    {        private const int PooledFrameLength = 1024;        [TestMethod]        public void Release_PooledBacking_ReturnsBufferToSmallPool()        {            var buffer = MemoryPoolManager.Rent(PooledFrameLength);            var message = CreateMessage(                new ReadOnlyMemory<byte>(buffer, 0, PooledFrameLength), buffer, PooledFrameLength, true);            var before = MemoryPoolManager.GetStatistics().SmallPoolReturned;            message.Release();            var after = MemoryPoolManager.GetStatistics().SmallPoolReturned;            Assert.AreEqual(before + 1, after, "池化背衬应在引用计数归零时归还到小池。");            Assert.IsTrue(message.IsReleased);            Assert.IsTrue(message.IsPooled);        }        [TestMethod]        public void Release_NonPooledBacking_DoesNotTouchPoolCounters()        {            var exact = new byte[64];            var message = CreateMessage(new ReadOnlyMemory<byte>(exact), exact, exact.Length, false);            var before = MemoryPoolManager.GetStatistics().SmallPoolReturned;            message.Release();            var after = MemoryPoolManager.GetStatistics().SmallPoolReturned;            Assert.AreEqual(before, after, "非池化背衬归还时只丢引用，不得计入归还计数。");            Assert.IsTrue(message.IsReleased);            Assert.IsFalse(message.IsPooled);        }        [TestMethod]        public void Release_Repeated_IsIdempotentAndReturnsOnce()        {            var buffer = MemoryPoolManager.Rent(PooledFrameLength);            var message = CreateMessage(                new ReadOnlyMemory<byte>(buffer, 0, PooledFrameLength), buffer, PooledFrameLength, true);            var before = MemoryPoolManager.GetStatistics().SmallPoolReturned;            message.Release();            message.Release();            message.Release();            var after = MemoryPoolManager.GetStatistics().SmallPoolReturned;            Assert.AreEqual(before + 1, after, "重复 Release 不得重复归还。");            Assert.IsTrue(message.IsReleased);        }        [TestMethod]        public void Frame_AfterRelease_ThrowsObjectDisposedException()        {            var exact = new byte[32];            var message = CreateMessage(new ReadOnlyMemory<byte>(exact), exact, exact.Length, false);            message.Release();            Assert.ThrowsException<ObjectDisposedException>(() => message.Frame.ToArray());        }        [TestMethod]        public void Retain_DefersReturnUntilLastRelease()        {            var buffer = MemoryPoolManager.Rent(PooledFrameLength);            var message = CreateMessage(                new ReadOnlyMemory<byte>(buffer, 0, PooledFrameLength), buffer, PooledFrameLength, true);            var before = MemoryPoolManager.GetStatistics().SmallPoolReturned;            message.Retain();            message.Release();            Assert.AreEqual(before, MemoryPoolManager.GetStatistics().SmallPoolReturned,                "Retain 之后第一次 Release 只减计数，不归还背衬。");            Assert.IsFalse(message.IsReleased);            message.Release();            Assert.AreEqual(before + 1, MemoryPoolManager.GetStatistics().SmallPoolReturned,                "最后一份引用释放时才归还背衬。");            Assert.IsTrue(message.IsReleased);        }        [TestMethod]        public void Retain_AfterRelease_ThrowsObjectDisposedException()        {            var exact = new byte[32];            var message = CreateMessage(new ReadOnlyMemory<byte>(exact), exact, exact.Length, false);            message.Release();            Assert.ThrowsException<ObjectDisposedException>(() => message.Retain());        }        private static PooledMessage CreateMessage(            ReadOnlyMemory<byte> frame, byte[] buffer, int originalSize, bool isPooled)        {            return new PooledMessage(frame, buffer, originalSize, isPooled);        }    }}